    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg]
    vals=Counter(v for _,_,v in cells)
    nonbg=[v for v in vals if v!=bg]
    wall=max(nonbg,key=lambda v:vals[v])
    marks=[(r,c) for r,c,v in cells if v!=wall]
    wc=[(r,c) for r,c,v in cells if v==wall]
    pts=set(wc); segs=[]
    while pts:
        seed=min(pts); comp=[seed]; pts.discard(seed); stack=[seed]
        while stack:
            a,b=stack.pop()
            for cand in list(pts):
                if abs(cand[0]-a)+abs(cand[1]-b)<=2:
                    comp.append(cand); pts.discard(cand); stack.append(cand)
        segs.append(comp)
    def seg_info(comp):
        rows=sorted(set(r for r,c in comp)); cols=sorted(set(c for r,c in comp))
        if len(cols)<len(rows):
            return ('v', cols[0], rows[0], len(rows))
        else:
            return ('h', rows[0], cols[0], len(cols))
    info=[seg_info(c) for c in segs]
    if len(info)==1: info=[info[0],info[0]]
    out=[r[:] for r in g]
    def fill(r,c,v):
        if 0<=r<H and 0<=c<W and out[r][c]==bg: out[r][c]=v
    for r,c in marks:
        mv=g[r][c]
        own=None
