        if own is None: continue
        o,p0,s,n=info[own]
        oo,op0,os_,on=info[1-own]
        off=os_-s
        if o=='v':
            d=1 if c>p0 else -1
            for cc in range(p0+d,c,d): fill(r,cc,mv)
            out[r][c]=4
            if oo=='v':
                rr=r+off; dd=1 if op0<W/2 else -1
                cc=op0+dd
                while 0<=cc<W and out[rr][cc]==bg:
                    out[rr][cc]=mv; cc+=dd
            else:
                cc2=c+off; dd=1 if op0<H/2 else -1
                rr2=op0+dd
                while 0<=rr2<H and out[rr2][cc2]==bg:
                    out[rr2][cc2]=mv; rr2+=dd
        else:
            d=1 if r>p0 else -1
            for rr in range(p0+d,r,d): fill(rr,c,mv)
            out[r][c]=4
            if oo=='h':
                cc2=c+off; dd=1 if op0<H/2 else -1
